def clean(df):
    df = df.copy()
    # Fix region label variants
    region_map = {
        'north': 'North', 'Nort': 'North',
        'east': 'East',
        'Suoth': 'South',
        'Wst': 'West',
    }
    df['Region'] = df['Region'].replace(region_map)
    # Parse Price written as text (e.g. '$350.00', '$6.00')
    df['Price'] = pd.to_numeric(
        df['Price'].astype(str).str.replace('$', '', regex=False).str.replace(',', '', regex=False),
        errors='coerce'
    )
    # Fix invalid dates like '2026-14-01' (day/month swapped)
    def fix_date(s):
        s = str(s).strip()
        try:
            return pd.to_datetime(s, format='%Y-%m-%d').strftime('%Y-%m-%d')
        except ValueError:
            parts = s.split('-')
            if len(parts) == 3:
                y, a, b = parts
                try:
                    return pd.to_datetime(f'{y}-{b}-{a}', format='%Y-%m-%d').strftime('%Y-%m-%d')
                except ValueError:
                    return pd.NaT
            return pd.NaT
    df['Date'] = df['Date'].apply(fix_date)
    # Recompute Revenue where possible
    mask = df['Price'].notna() & df['Quantity'].notna()
    df.loc[mask, 'Revenue'] = df.loc[mask, 'Quantity'] * df.loc[mask, 'Price']
    return df

def answer(df):
    d = df.dropna(subset=['Region', 'Quantity'])
    units = d.groupby('Region')['Quantity'].sum()
    return {str(k): int(v) for k, v in units.items()}
